begin;
insert into auth.users(id,raw_user_meta_data) values ('ef610000-0000-4000-8000-000000000001','{}'),('ef610000-0000-4000-8000-000000000002','{}');
alter table public.profiles disable trigger guard_profile_privileges;
update public.profiles set role='OWNER',is_active=true where id='ef610000-0000-4000-8000-000000000001';
update public.profiles set role='STAFF',is_active=true where id='ef610000-0000-4000-8000-000000000002';
alter table public.profiles enable trigger guard_profile_privileges;
insert into public.coa_accounts(code,name,type,normal_balance) values('5501','Bank fee','BEBAN','D') on conflict(code) do nothing;
create function pg_temp.assert_true(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'ASSERTION FAILED: %',label; end if;end$$;
create function pg_temp.expect_error(statement text,fragment text) returns void language plpgsql as $$begin begin execute statement;raise exception 'Expected failure';exception when others then if position(fragment in sqlerrm)=0 then raise;end if;end;end$$;
create function pg_temp.reject_transfer_line() returns trigger language plpgsql as $$begin if exists(select 1 from public.journal_entries where id=new.entry_id and deskripsi like '%Injected failure%') and new.credit>0 then raise exception 'INJECTED_TRANSFER_FAILURE';end if;return new;end$$;
create trigger transfer_test_failure before insert on public.journal_lines for each row execute function pg_temp.reject_transfer_line();
update public.accounting_locks set closed_until=null where id;
create temp table transfer_input(header jsonb);
insert into transfer_input select jsonb_build_object('tanggal',current_date-1,'from_account_id',(select id from public.cash_accounts where coa_code='1101'),'to_account_id',(select id from public.cash_accounts where coa_code='1102'),'jumlah',100.25,'biaya_admin',1.25,'branch_id',null,'keterangan','Transfer fixture');
create temp table transfer_result(result jsonb);
grant all on transfer_input,transfer_result to authenticated;
grant insert,update,delete on public.cash_transfers to authenticated;
create policy transfer_test_direct_write on public.cash_transfers for all to authenticated using(true) with check(true);
set local role authenticated;
select set_config('request.jwt.claim.sub','ef610000-0000-4000-8000-000000000001',true);
insert into transfer_result select public.mutate_cash_transfer('transfer-create','create',null,null,(select header from transfer_input),null);
select pg_temp.assert_true((select result->>'transfer_id' is not null from transfer_result),'create confirms transfer');
select pg_temp.assert_true(public.mutate_cash_transfer('transfer-create','create',null,null,(select header from transfer_input),null)=(select result from transfer_result),'identical create returns original');
select pg_temp.assert_true((select count(*)=1 from public.cash_transfers),'retry does not duplicate transfer');
select pg_temp.assert_true((select sum(debit)=101.50 and sum(credit)=101.50 and count(*)=3 from public.journal_lines),'transfer and fee balanced exactly');
select pg_temp.expect_error($q$select public.mutate_cash_transfer('transfer-create','create',null,null,jsonb_set((select header from transfer_input),'{jumlah}','200'),null)$q$,'rincian berbeda');
select pg_temp.expect_error($q$select public.mutate_cash_transfer('bad-cent','create',null,null,jsonb_set((select header from transfer_input),'{jumlah}','100.251'),null)$q$,'Nilai');
select pg_temp.expect_error($q$select public.mutate_cash_transfer('bad-fee','create',null,null,jsonb_set((select header from transfer_input),'{biaya_admin}','-1'),null)$q$,'Nilai');
select pg_temp.expect_error($q$select public.mutate_cash_transfer('future','create',null,null,jsonb_set((select header from transfer_input),'{tanggal}',to_jsonb(current_date+1)),null)$q$,'Tanggal');
select pg_temp.expect_error($q$select public.mutate_cash_transfer('rollback-create','create',null,null,jsonb_set((select header from transfer_input),'{keterangan}','"Injected failure"'),null)$q$,'INJECTED_TRANSFER_FAILURE');
select pg_temp.assert_true((select count(*)=1 from public.cash_transfers),'failed create leaves no header');
select public.mutate_cash_transfer('transfer-edit','edit',(select (result->>'transfer_id')::uuid from transfer_result),0,jsonb_set((select header from transfer_input),'{jumlah}','200.50'),'Koreksi jumlah');
select pg_temp.assert_true((select jumlah=200.50 and revision=1 from public.cash_transfers),'edit replaces amount once');
select pg_temp.assert_true((select sum(credit-debit)=201.75 from public.journal_lines where account_id=(select id from public.coa_accounts where code='1101')),'edit reverses old effect and applies new amount');
select pg_temp.expect_error($q$select public.mutate_cash_transfer('stale','void',(select (result->>'transfer_id')::uuid from transfer_result),0,'{}','Stale edit')$q$,'berubah');
select public.mutate_cash_transfer('transfer-void','void',(select (result->>'transfer_id')::uuid from transfer_result),1,'{}','Batalkan simulasi');
select public.mutate_cash_transfer('transfer-void','void',(select (result->>'transfer_id')::uuid from transfer_result),1,'{}','Batalkan simulasi');
select pg_temp.assert_true((select voided_at is not null and revision=2 from public.cash_transfers),'void increments revision once');
select pg_temp.assert_true(not exists(select account_id from public.journal_lines group by account_id having sum(debit-credit)<>0),'void neutralizes all account effects');
select pg_temp.assert_true((select count(*)=2 from public.cash_transfer_revisions),'edit and void retain audits');
select pg_temp.expect_error($q$update public.cash_transfers set jumlah=1$q$,'jalur resmi');
select pg_temp.expect_error($q$delete from public.journal_entries where source='transfer'$q$,'jalur resmi');
select pg_temp.expect_error($q$update public.journal_lines set debit=0 where entry_id in (select id from public.journal_entries where source='transfer')$q$,'jalur resmi');
select pg_temp.expect_error($q$delete from public.cash_transfer_revisions$q$,'permission denied');
reset role;
drop policy transfer_test_direct_write on public.cash_transfers;
set local role authenticated;
select set_config('request.jwt.claim.sub','ef610000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true(not exists(select 1 from public.cash_transfers),'staff cannot read transfer history');
select pg_temp.expect_error($q$select public.mutate_cash_transfer('staff','create',null,null,(select header from transfer_input),null)$q$,'Akses transfer');
select set_config('request.jwt.claim.sub','ef610000-0000-4000-8000-000000000001',true);
reset role;
select pg_temp.assert_true((select count(*)=3 from public.cash_transfer_requests),'failed requests leave no orphan');
update public.profiles set is_active=false where id='ef610000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.expect_error($q$select public.mutate_cash_transfer('transfer-create','create',null,null,(select header from transfer_input),null)$q$,'Akses transfer');
reset role;
alter table public.profiles disable trigger guard_profile_privileges;
update public.profiles set is_active=true where id='ef610000-0000-4000-8000-000000000001';
alter table public.profiles enable trigger guard_profile_privileges;
set local role authenticated;
delete from transfer_result;
insert into transfer_result select public.mutate_cash_transfer('second-create','create',null,null,(select header from transfer_input),null);
select pg_temp.expect_error($q$select public.mutate_cash_transfer('failed-edit','edit',(select (result->>'transfer_id')::uuid from transfer_result),0,jsonb_set((select header from transfer_input),'{keterangan}','"Injected failure"'),'Failure rollback')$q$,'INJECTED_TRANSFER_FAILURE');
select pg_temp.assert_true((select jumlah=100.25 and revision=0 from public.cash_transfers where id=(select (result->>'transfer_id')::uuid from transfer_result)),'failed edit preserves original transfer');
select pg_temp.assert_true((select count(*)=5 from public.journal_entries),'failed edit rolls back reversal and replacement journals');
reset role;
select pg_temp.assert_true(not exists(select 1 from public.cash_transfer_requests where request_key='failed-edit'),'failed edit leaves no request');
update public.accounting_locks set closed_until=current_date-1 where id;
set local role authenticated;
select pg_temp.expect_error($q$select public.mutate_cash_transfer('closed-create','create',null,null,(select header from transfer_input),null)$q$,'ditutup');
select pg_temp.expect_error($q$select public.mutate_cash_transfer('closed-void','void',(select (result->>'transfer_id')::uuid from transfer_result),0,'{}','Closed original')$q$,'ditutup');
reset role;
update public.accounting_locks set closed_until=current_date-2 where id;
set local role authenticated;
select pg_temp.expect_error($q$select public.mutate_cash_transfer('closed-target','edit',(select (result->>'transfer_id')::uuid from transfer_result),0,jsonb_set((select header from transfer_input),'{tanggal}',to_jsonb(current_date-2)),'Closed target')$q$,'ditutup');
reset role;
update public.accounting_locks set closed_until=null where id;
alter table public.profiles disable trigger guard_profile_privileges;
update public.profiles set role='ADMIN' where id='ef610000-0000-4000-8000-000000000002';
alter table public.profiles enable trigger guard_profile_privileges;
set local role authenticated;
select set_config('request.jwt.claim.sub','ef610000-0000-4000-8000-000000000002',true);
select public.mutate_cash_transfer('admin-create','create',null,null,(select header from transfer_input),null);
reset role;
insert into public.role_modules(role,module_id) values('ADMIN','pengaturan');
set local role authenticated;
select pg_temp.expect_error($q$select public.mutate_cash_transfer('admin-create','create',null,null,(select header from transfer_input),null)$q$,'Kas dan Bank');
select pg_temp.assert_true(not exists(select 1 from public.cash_transfers),'revoked module cannot read transfers');
reset role;
delete from public.role_modules where role='ADMIN';
alter table public.profiles disable trigger guard_profile_privileges;
update public.profiles set role='FINANCE' where id='ef610000-0000-4000-8000-000000000002';
alter table public.profiles enable trigger guard_profile_privileges;
insert into public.branches(id,code,name,type) values('ef620000-0000-4000-8000-000000000001','TFA','Transfer A','PETSHOP'),('ef620000-0000-4000-8000-000000000002','TFB','Transfer B','PETSHOP');
insert into public.user_branches(user_id,branch_id) values('ef610000-0000-4000-8000-000000000002','ef620000-0000-4000-8000-000000000001');
insert into public.role_capabilities(role,all_branches) values('FINANCE',false);
set local role authenticated;
select pg_temp.expect_error($q$select public.mutate_cash_transfer('wrong-branch','create',null,null,jsonb_set((select header from transfer_input),'{branch_id}','"ef620000-0000-4000-8000-000000000002"'),null)$q$,'Cabang transfer');
reset role;
update public.cash_accounts set branch_id='ef620000-0000-4000-8000-000000000002' where coa_code='1102';
set local role authenticated;
select pg_temp.expect_error($q$select public.mutate_cash_transfer('wrong-account','create',null,null,jsonb_set((select header from transfer_input),'{branch_id}','"ef620000-0000-4000-8000-000000000001"'),null)$q$,'Rekening transfer');
reset role;
update public.cash_accounts set branch_id=null where coa_code='1102';
set local role authenticated;
select pg_temp.assert_true(public.mutate_cash_transfer('finance-create','create',null,null,jsonb_set((select header from transfer_input),'{branch_id}','"ef620000-0000-4000-8000-000000000001"'),null)->>'transfer_id' is not null,'branch finance may use shared cash accounts in own branch');
reset role;
insert into public.coa_accounts(code,name,type,normal_balance) values('1103','Inactive branch bank','ASET','D');
insert into public.cash_accounts(id,nama,jenis,coa_code,branch_id) values('ef630000-0000-4000-8000-000000000001','Inactive branch bank','Bank','1103','ef620000-0000-4000-8000-000000000002');
update public.branches set is_active=false where id='ef620000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','ef610000-0000-4000-8000-000000000001',true);
select pg_temp.expect_error($q$select public.mutate_cash_transfer('inactive-target-account-branch','edit',(select (result->>'transfer_id')::uuid from transfer_result),0,jsonb_set((select header from transfer_input),'{to_account_id}','"ef630000-0000-4000-8000-000000000001"'),'Inactive replacement')$q$,'Cabang rekening transfer tidak aktif');
rollback;
